/* Replacement faces and fitted costumes share one transparent puppet atlas.
   Embedding it also keeps canvas hit testing available when index.html is opened locally. */
(() => {
  "use strict";
  const atlas = new Image();
  const rectangles = [[[3,3,204,231],[3,245,204,228],[3,487,204,220],[3,729,161,236],[3,971,164,236]],[[213,3,204,178],[213,245,204,192],[213,487,204,185],[213,729,171,236],[213,971,171,236]],[[423,3,204,227],[423,245,204,208],[423,487,204,216],[423,729,168,236],[423,971,166,236]],[[633,3,204,213],[633,245,204,208],[633,487,204,207],[633,729,162,236],[633,971,161,236]],[[843,3,174,236],[843,245,187,236],[843,487,178,236],[843,729,129,236],[843,971,130,236]],[[1053,3,198,236],[1053,245,204,235],[1053,487,203,236],[1053,729,178,236],[1053,971,179,236]],[[1263,3,204,211],[1263,245,204,222],[1263,487,204,217],[1263,729,189,236],[1263,971,188,236]],[[1473,3,204,195],[1473,245,204,189],[1473,487,204,202],[1473,729,133,236],[1473,971,134,236]],[[1683,3,204,235],[1683,245,204,223],[1683,487,204,218],[1683,729,161,236],[1683,971,161,236]],[[1893,3,196,236],[1893,245,201,236],[1893,487,204,234],[1893,729,166,236],[1893,971,164,236]],[[2103,3,204,218],[2103,245,204,214],[2103,487,204,205],[2103,729,160,236],[2103,971,156,236]],[[2313,3,204,232],[2313,245,204,228],[2313,487,204,229],[2313,729,168,236],[2313,971,167,236]],[[2523,3,192,236],[2523,245,204,235],[2523,487,203,236],[2523,729,159,236],[2523,971,160,236]]]; // ATLAS_RECTANGLES
  let ready = false;
  atlas.onload = () => { ready = true; };

  function stamp(ctx, id, row, bounds) {
    if (!ready || !Number.isInteger(id) || id < 0 || id >= rectangles.length) return false;
    const source = rectangles[id][row];
    ctx.drawImage(atlas, ...source, ...bounds);
    return true;
  }

  function draw(ctx, id, pose) {
    if (id === "player") id = 0;
    if (!ready || !rectangles[id]) return false;
    const row = pose.back ? 2 : pose.profile || pose.turn > 0.60 ? 1 : 0;
    const [, , sw, sh] = rectangles[id][row];
    const longerHair = id === 6 || id === 11;
    const height = longerHair ? 50 : id === 4 ? 48 : 44;
    const width = Math.min(row === 1 ? 42 : 44, height * sw / sh);
    const hem = longerHair ? 9 : 3;
    ctx.save();
    ctx.translate(row === 1 ? 2 : 0, pose.down ? 0.8 : 0);
    const painted = stamp(ctx,id,row,[-width / 2,hem - height,width,height]);
    ctx.restore();
    return painted;
  }

  function torso(ctx, id, pose) {
    if (id === "player") return false;
    const isCoat = id === 4 || id === 7;
    const width = isCoat ? 55 : 53;
    const top = -74;
    return stamp(ctx,id,pose.back ? 4 : 3,[-width / 2,top,width,(isCoat ? 22 : 2) - top]);
  }

  window.ClayHeads = {
    draw, torso,
    get ready() { return ready; },
    get atlasImage() { return atlas; },
    get atlasRects() { return rectangles; }
  };
  atlas.src = "data:image/webp;base64,"; // ATLAS_IMAGE
})();
